    },
    "assessment": {
      "urgency": "unknown",
      "rationale": "Growth rate unknown: cannot rank urgency from a percentage alone. While the user context mentions 'critical', the computed analysis lacks the metrics (growth rate, available bytes) required to determine actual time-to-exhaustion."
    },
    "facts": [
      "Alert received for host db-7",
      "User reports severity as critical",
      "No specific metric values (used_pct, available_gib, etc.) were provided in the observed facts"
    ],
    "missing_context": [
      {
        "item": "filesystem_available_bytes",
        "why": "To determine how much actual space remains before exhaustion.",
        "how_to_check": "df -h"
      },
      {
        "item": "filesystem_size_bytes",
        "why": "To calculate the percentage of capacity used.",
        "how_to_check": "df -h"
      },
      {
        "item": "growth_rate_bytes_per_hour",
        "why": "To calculate time-to-exhaustion (TTE) and determine urgency.",
        "how_to_check": "predict_linear(node_filesystem_avail_bytes{instance='db-7'}[6h], 4*3600)"
      }
    ],
    "immediate_actions": [
      {
        "action": "Identify top growing directories",
        "purpose": "Locate the source of disk consumption to decide on mitigation.",
        "conditions": "Upon gaining shell access to db-7",
        "expected_effect": "Pinpoint if the growth is in logs, data, or other system directories.",
        "risks": "None",
        "requires_approval": false,
        "verify": "Check output of du command",
        "rule_ids": [
          "linux.storage.004"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Check for deleted files held open by processes",
        "hypothesis": "Space was 'freed' by a deletion but not reclaimed by the OS because a process still holds the file handle.",
        "how_to_check": "lsof +L1 or lsof -nP | grep '(deleted)'"
      },
      {
        "step": "Analyze log usage",
        "hypothesis": "Runaway logging or debug mode is consuming space in /var/log.",
        "how_to_check": "du -xh --max-depth=2 /var | sort -h | tail; journalctl --disk-usage"
      },
      {
        "step": "Check database data directory size",
        "hypothesis": "The database itself is growing due to data ingestion or lack of retention.",
        "how_to_check": "du -sh /var/lib/mongodb /var/lib/postgresql (or relevant DB path)"
      }
    ],
    "root_cause_hypotheses": [
      "Runaway application/system logs",
      "Database data growth exceeding capacity",
      "Deleted files still held open by active processes",
      "Unexpected large file creation (e.g., core dumps, temp files)"
    ],
    "dangerous_operations": [
      {
        "operation": "Cleaning up inside database data directories",
        "why_dangerous": "Deleting files in database directories can cause permanent data corruption.",
        "rule_id": "linux.storage.006"
      },
      {
        "operation": "Restarting production database processes",
        "why_dangerous": "May cause service downtime; should only be done to reclaim space from deleted files if no other option exists.",
        "rule_id": "linux.storage.003"
      },
      {
        "operation": "Removing reserved filesystem blocks",
        "why_dangerous": "Reduces the safety margin for system daemons, potentially leading to OS instability.",
        "rule_id": "linux.storage.005"
      }
    ],
    "applied_expert_rules": [
      "global.evidence.001",
      "linux.storage.004",
      "linux.storage.003",
      "linux.storage.006"
    ],
